"""Official Latin American course starts, distinct age tracks and general stays."""
def add_latam_intake(add, src, fit, profiles):
    def put(*args, **kw):
        add(*args, **kw)
        p=profiles[-1]; p['checked']='2026-10-05'
        import re
        def readable(v):
            if not isinstance(v,str): return v
            v=re.sub(r'([А-Яа-яЁё])([A-Za-z0-9])',r'\1 \2',v)
            v=re.sub(r'([A-Za-z0-9])([А-Яа-яЁё])',r'\1 \2',v)
            v=re.sub(r'([;,])(?=[А-Яа-яЁёA-Za-z0-9])',r'\1 ',v)
            for x,y in {'Толькопосле':'Только после','наоктябрь':'на октябрь','Цена публичной октябрьской':'Цена публичной октябрьской','вКолумбии':'в Колумбии','пока6':'пока 6','языклагерной':'язык лагерной','ночёвку299неумножать':'ночёвку 299 не умножать','Ночёвку299неумножать':'Ночёвку 299 не умножать','недатированная смета':'недатированная смета','Английскийотдых':'Английский отдых','Братьяразного':'Братья разного','точныйадрес':'точный адрес','перечёркнутыйпрайс':'перечёркнутый прайс','freeplace':'free place','Нетпо':'Нет по','Возрастподходит':'Возраст подходит','Языкподтвердить':'Язык подтвердить','Кандидатнаобщие':'Кандидат на общие','климатизированныхшале':'климатизированных шале','учебныйдопуск':'учебный допуск','Условияоператора':'Условия оператора','общийлагерь':'общий лагерь','фактическиеместа':'фактические места','приёмоведы':'приёмов еды','наточность':'на точность','безэкраннаяпрограмма':'безэкранная программа','экранывыключены':'экраны выключены','новыйгод':'новый год','Толькоесли':'Только если','некурс':'не курс','после7-летия':'после 7-летия','готовностькночёвкам':'готовность к ночёвкам','неподтверждённое':'неподтверждённое','новые2027':'новые 2027','площадки30':'площадки 30','не опубликованы':'не опубликованы'}.items(): v=v.replace(x,y)
            return v
        for k in ['provider','place','age','language','programme','editorial_reason','accommodation']:
            p[k]=readable(p[k])
        p['timing']['label']=readable(p['timing']['label'])
        for k in ['label','included','extras','deposit']:p['price'][k]=readable(p['price'][k])
        for k in ['matvey','oscar']:p['family_fit'][k]['detail']=readable(p['family_fit'][k]['detail'])
        p['questions']=[readable(x) for x in p['questions']]
        for x in p['sources']:x['title']=readable(x['title'])
        for s in p['sources']: s['checked']=p['checked']
        return p
    def fee(year,label,included,extras,deposit):
        return dict(year=year,label=label,included=included,extras=extras,deposit=deposit)
    def dated(p, rows):
        p['timing']['session_details']=rows
        p['timing']['sessions']=[[x['start'],x['end']] for x in rows]
    def row(p,start,end,label,price,url,scope='camp_session',**kw):
        return dict(start=start,end=end,label=label,price=price,source=url,place=p['place'],formats=p['formats'],date_scope=scope,**kw)
